public class Solution {
    public int maxSumMinProduct(int[] nums) {
        int n = nums.length;
        long[] prefixSum = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + nums[i];
        }

        Stack<Integer> stack = new Stack<>();
        int maxMinProduct = 0;
        int mod = 1000000007;

        for (int i = 0; i <= n; i++) {
            while (!stack.isEmpty() && (i == n || nums[stack.peek()] > (i == n ? 0 : nums[i]))) {
                int top = stack.pop();
                long minVal = nums[top];
                long sum = prefixSum[i] - prefixSum[top];
                long product = (minVal * sum) % mod;
                maxMinProduct = (int) Math.max(maxMinProduct, product);
            }
            stack.push(i);
        }

        return maxMinProduct;
    }
}

