    public int solve(String expression) {
        return solveHelper(expression).minFlips;
    }

    private Result solveHelper(String expression) {
        if (expression.length() == 1) {
            if (expression.equals("1")) {
                return new Result(1, 0);
            } else {
                return new Result(0, 0);
            }
        }

        Stack<Character> ops = new Stack<>();
        Stack<Integer> nums = new Stack<>();
        int minFlips = 0;

        for (int i = 0; i < expression.length(); i++) {
            char c = expression.charAt(i);

            if (c == '(') {
                ops.push(c);
            } else if (c == ')') {
                while (!ops.isEmpty() && ops.peek() != '(') {
                    char op = ops.pop();
                    int num2 = nums.pop();
                    int num1 = nums.pop();
                    int result;
                    if (op == '&') {
                        result = num1 & num2;
                    } else {
                        result = num1 | num2;
                    }
                    nums.push(result);
                }
                ops.pop(); // Pop the '('
            } else if (c == '&' || c == '|') {
                while (!ops.isEmpty() && precedence(ops.peek()) >= precedence(c)) {
                    char op = ops.pop();
                    int num2 = nums.pop();
                    int num1 = nums.pop();
                    int result;
                    if (op == '&') {
                        result = num1 & num2;
                    } else {
                        result = num1 | num2;
                    }
                    nums.push(result);
                }
                ops.push(c);
            } else {
                nums.push(c - '0');
            }
        }

        while (!ops.isEmpty()) {
            char op = ops.pop();
            int num2 = nums.pop();
            int num1 = nums.pop();
            int result;
            if (op == '&') {
                result = num1 & num2;
            } else {
                result = num1 | num2;
            }
            nums.push(result);
        }

        int finalValue = nums.pop();
        if (finalValue == 0) {
            return new Result(0, 0);
        } else {
            return new Result(1, 0);
        }
    }

    private int precedence(char op) {
        if (op == '&') {
            return 1;
        } else if (op == '|') {
            return 1;
        } else {
            return 0;
        }
    }
}

