        int flips1 = 0;
        int flips2 = 0;

        for (int i = 0; i < n; i++) {
            if (i % 2 == 0) {
                if (s.charAt(i) != '0') {
                    flips1++;
                }
                if (s.charAt(i) != '1') {
                    flips2++;
                }
            } else {
                if (s.charAt(i) != '1') {
                    flips1++;
                }
                if (s.charAt(i) != '0') {
                    flips2++;
                }
            }
        }

        int minFlips = Math.min(flips1, flips2);

        for (int i = 0; i < n; i++) {
            String rotated = s.substring(1) + s.charAt(0);
            s = rotated;

            flips1 = 0;
            flips2 = 0;

            for (int j = 0; j < n; j++) {
                if (j % 2 == 0) {
                    if (s.charAt(j) != '0') {
                        flips1++;
                    }
                    if (s.charAt(j) != '1') {
                        flips2++;
                    }
                } else {
                    if (s.charAt(j) != '1') {
                        flips1++;
                    }
                    if (s.charAt(j) != '0') {
                        flips2++;
                    }
                }
            }
            minFlips = Math.min(minFlips, Math.min(flips1, flips2));
        }

        return minFlips;
    }
