// #Hard #Dynamic_Programming #Math #Combinatorics
// #2022_05_10_Time_67_ms_(96.33%)_Space_55.1_MB_(80.73%)
import java.util.Arrays;
public class Solution {
    public int rearrangeSticks(int n, int k) {
        long mod = 1000000007;
        long[][] dp = new long[n + 1][k + 1];
        dp[0][0] = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= k; j++) {
                for (int l = 0; l <= Math.min(j, i - 1); l++) {
                    dp[i][j] = (dp[i][j] + dp[i - 1][j - l] * combinations(i - 1, l, mod)) % mod;
                }
            }
        }
        return (int) dp[n][k];
    }

    private long combinations(int n, int k, long mod) {
        if (k < 0 || k > n) {
            return 0;
        }
        if (k == 0 || k == n) {
            return 1;
        }
        if (k > n / 2) {
            k = n - k;
        }
        long result = 1;
        for (int i = 1; i <= k; i++) {
            result = (result * (n - i + 1)) % mod;
            long inv = power(i, mod - 2, mod);
            result = (result * inv) % mod;
        }
        return result;
    }

    private long power(long base, long exp, long mod) {
        long res = 1;
        base %= mod;
        while (exp > 0) {
            if (exp % 2 == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp /= 2;
        }
        return res;
    }
}

