public class Solution {
    public int[] earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        int earliest = 1;
        int latest = 0;

        if (firstPlayer > secondPlayer) {
            int temp = firstPlayer;
            firstPlayer = secondPlayer;
            secondPlayer = temp;
        }

        int rounds = 0;
        while (n > 0) {
            rounds++;
            n = (n + 1) / 2;
        }

        latest = rounds;

        int dist = Math.abs(firstPlayer - secondPlayer);
        if (dist == 1) {
            earliest = 1;
        } else {
            int round = 1;
            int players = n;
            while (players > 0) {
                if (players == 1) {
                    break;
                }
                int half = players / 2;
                if (firstPlayer <= half && secondPlayer > half) {
                    earliest = round;
                    break;
                }
                if (firstPlayer > half && secondPlayer <= half) {
                    earliest = round;
                    break;
                }
                players = (players + 1) / 2;
                round++;
            }
        }

        if (firstPlayer == 1 && secondPlayer == n) {
            earliest = 1;
            latest = rounds;
        }

        if (firstPlayer == 1 && secondPlayer == 2) {
            earliest = 1;
            latest = rounds;
        }

        if (firstPlayer == n && secondPlayer == 1) {
            earliest = 1;
            latest = rounds;
        }

        if (firstPlayer == n && secondPlayer == n - 1) {
            earliest = 1;
            latest = rounds;
        }

        return new int[]{earliest, latest};
    }
}

