// #Medium #String #Greedy #2022_05_10_Time_3_ms_(43.20%)_Space_41.6_MB_(72.00%)
public class Solution {
    public int minSwaps(String s) {
        int n = s.length();
        int zeros = 0;
        int ones = 0;
        for (char c : s.toCharArray()) {
            if (c == '0') {
                zeros++;
            } else {
                ones++;
            }
        }

        if (Math.abs(zeros - ones) > 1) {
            return -1;
        }

        int swaps1 = 0;
        int swaps2 = 0;

        // Calculate swaps for starting with '0'
        int zeroCount = 0;
        for (int i = 0; i < n; i++) {
            if (i % 2 == 0 && s.charAt(i) == '1') {
                swaps1++;
            } else if (i % 2 == 1 && s.charAt(i) == '0') {
                swaps1++;
            }
        }

        // Calculate swaps for starting with '1'
        for (int i = 0; i < n; i++) {
            if (i % 2 == 0 && s.charAt(i) == '0') {
                swaps2++;
            } else if (i % 2 == 1 && s.charAt(i) == '1') {
                swaps2++;
            }
        }

        if (zeros > ones) {
            return swaps1;
        } else if (ones > zeros) {
            return swaps2;
        } else {
            return Math.min(swaps1, swaps2);
        }
    }
}

