    public int[] closestRoom(int[][] rooms, int[][] queries) {
        Arrays.sort(rooms, (a, b) -> a[1] - b[1]);
        int k = queries.length;
        int[] answer = new int[k];
        for (int i = 0; i < k; i++) {
            int preferred = queries[i][0];
            int minSize = queries[i][1];
            int bestRoomId = -1;
            int minDiff = Integer.MAX_VALUE;
            for (int[] room : rooms) {
                if (room[1] >= minSize) {
                    int diff = Math.abs(room[0] - preferred);
                    if (diff < minDiff) {
                        minDiff = diff;
                        bestRoomId = room[0];
                    } else if (diff == minDiff && room[0] < bestRoomId) {
                        bestRoomId = room[0];
                    }
                }
            }
            answer[i] = bestRoomId;
        }
        return answer;
    }
}

