import java.util.HashMap;
public class Solution {
    public int nicePairCount(int[] nums) {
        long count = 0;
        long mod = 1000000007;
        HashMap<Integer, Integer> map = new HashMap<>();
        for (int num : nums) {
            int rev = reverse(num);
            int diff = num - rev;
            if (map.containsKey(diff)) {
                count = (count + map.get(diff)) % mod;
                map.put(diff, map.get(diff) + 1);
            } else {
                map.put(diff, 1);
            }
        }
        return (int) count;
    }

    private int reverse(int x) {
        int rev = 0;
        while (x > 0) {
            int digit = x % 10;
            rev = rev * 10 + digit;
            x /= 10;
        }
        return rev;
    }
}

