import java.util.Arrays;
import java.util.Comparator;
import java.util.PriorityQueue;

public class Solution {
    public int[] minInterval(int[][] intervals, int[] queries) {
        int n = intervals.length;
        int m = queries.length;
        int[] ans = new int[m];
        Arrays.fill(ans, -1);

        // Sort intervals by start time
        Arrays.sort(intervals, Comparator.comparingInt(a -> a[0]));

        // Use a priority queue to store intervals that contain the current query
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[1] - a[0] + 1));

        int i = 0;
        for (int query : queries) {
            // Add intervals that start before or at the query
            while (i < n && intervals[i][0] <= query) {
                pq.offer(intervals[i]);
                i++;
            }

            // Remove intervals that end before the query
            while (!pq.isEmpty() && pq.peek()[1] < query) {
                pq.poll();
            }

            // If there are any intervals left in the priority queue, the smallest one is the answer
            if (!pq.isEmpty()) {
                ans[Arrays.asList(queries).indexOf(query)] = pq.peek()[1] - pq.peek()[0] + 1;
            }
        }

        return ans;
    }
}

