public class Solution {
    public int maximizeResult(int n, int index, int maxSum) {
        int left = 1;
        int right = maxSum;
        int ans = 0;

        while (left <= right) {
            int mid = (left + right) / 2;
            if (isValid(n, index, maxSum, mid)) {
                ans = mid;
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        return ans;
    }

    private boolean isValid(int n, int index, int maxSum, int peak) {
        long sum = peak;
        int left = index - 1;
        int right = n - index - 1;

        while (left > 0 || right > 0) {
            if (left > 0 && right > 0) {
                if (left >= right) {
                    sum += left;
                    left--;
                } else {
                    sum += right;
                    right--;
                }
            } else if (left > 0) {
                sum += left;
                left--;
            } else {
                sum += right;
                right--;
            }

            if (sum > maxSum) {
                return false;
            }
        }

        return true;
    }
}

