import java.util.Arrays;
public class Solution {
    public int minimumXORSum(int[] nums1, int[] nums2) {
        int n = nums1.length;
        int[][] dp = new int[1 << n][n];
        for (int i = 0; i < (1 << n); i++) {
            Arrays.fill(dp[i], Integer.MAX_VALUE);
        }
        dp[0][0] = 0;
        for (int mask = 0; mask < (1 << n); mask++) {
            for (int i = 0; i < n; i++) {
                if (dp[mask][i] != Integer.MAX_VALUE) {
                    for (int j = 0; j < n; j++) {
                        if ((mask & (1 << j)) == 0) {
                            dp[mask | (1 << j)][j] = Math.min(dp[mask | (1 << j)][j], dp[mask][i] + (nums1[i] ^ nums2[j]));
                        }
                    }
                }
            }
        }
        int minXorSum = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            minXorSum = Math.min(minXorSum, dp[(1 << n) - 1][i]);
        }
        return minXorSum;
    }
}

