import java.util.HashSet;
import java.util.PriorityQueue;
import java.util.Set;

public class Solution {
    public int[] getBiggestThree(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        Set<Integer> sums = new HashSet<>();

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                // Iterate through all possible sizes of the rhombus
                for (int size = 0; size <= Math.min(m, n); size++) {
                    // Calculate the sum of the rhombus with center at (i, j) and size 'size'
                    int sum = 0;
                    for (int row = i - size; row <= i + size; row++) {
                        for (int col = j - size; col <= j + size; col++) {
                            if (row >= 0 && row < m && col >= 0 && col < n && Math.abs(row - i) + Math.abs(col - j) <= size) {
                                sum += grid[row][col];
                            }
                        }
                    }
                    sums.add(sum);
                }
            }
        }

        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> b - a);
        pq.addAll(sums);

        int[] result = new int[Math.min(3, sums.size())];
        for (int i = 0; i < result.length; i++) {
            result[i] = pq.poll();
        }

        return result;
    }
}

