// #Hard #Array #Dynamic_Programming #2022_05_10_Time_70_ms_(73.08%)_Space_74.5_MB_(36.54%)
public class Solution {
    public int minSkips(int[] dist, int speed, int hoursBefore) {
        int n = dist.length;
        int[][] dp = new int[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                dp[i][j] = Integer.MAX_VALUE;
            }
        }
        dp[0][0] = 0;

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                // Not skip
                double time = (double) dist[i - 1] / speed;
                int prevHour = dp[i - 1][j];
                if (prevHour != Integer.MAX_VALUE) {
                    int currentHour = (int) Math.ceil(prevHour + time);
                    if (currentHour <= hoursBefore) {
                        dp[i][j] = Math.min(dp[i][j], currentHour);
                    }
                }

                // Skip
                if (j > 0) {
                    time = (double) dist[i - 1] / speed;
                    int prevHour = dp[i - 1][j - 1];
                    if (prevHour != Integer.MAX_VALUE) {
                        int currentHour = prevHour + (int) Math.ceil(time);
                        if (currentHour <= hoursBefore) {
                            dp[i][j] = Math.min(dp[i][j], currentHour);
                        }
                    }
                }
            }
        }

        int minSkips = Integer.MAX_VALUE;
        for (int j = 0; j <= n; j++) {
            if (dp[n][j] != Integer.MAX_VALUE) {
                minSkips = Math.min(minSkips, j);
            }
        }

        if (minSkips == Integer.MAX_VALUE) {
            return -1;
        }

        return minSkips;
    }
}

