            if (wastedSpace != Long.MAX_VALUE) {
                minWastedSpace = Math.min(minWastedSpace, wastedSpace);
            }
        }
        if (minWastedSpace == Long.MAX_VALUE) {
            return -1;
        }
        return (int) (minWastedSpace % 1000000007);
    }
}

