// #Medium #Array #Sorting #Binary_Search #Ordered_Set #Binary_Search_II_Day_7
// #2022_05_03_Time_13_ms_(99.44%)_Space_78.1_MB_(33.15%)
public class Solution {
    public int minAbsoluteSumDiff(int[] nums1, int[] nums2) {
        int n = nums1.length;
        int sum = 0;
        int[] sortedNums1 = nums1.clone();
        Arrays.sort(sortedNums1);
        int mod = 1000000007;

        for (int i = 0; i < n; i++) {
            int diff = Math.abs(nums1[i] - nums2[i]);
            sum = (sum + diff) % mod;
        }

        int maxReduction = 0;
        for (int i = 0; i < n; i++) {
            int diff = Math.abs(nums1[i] - nums2[i]);
            int replacement = binarySearch(sortedNums1, nums2[i]);
            int newDiff = Math.abs(replacement - nums2[i]);
            int reduction = diff - newDiff;
            if (reduction > 0) {
                maxReduction = Math.max(maxReduction, reduction);
            }
        }

        return (sum - maxReduction + mod) % mod;
    }

    private int binarySearch(int[] arr, int target) {
        int left = 0;
        int right = arr.length - 1;
        int closest = arr[0];

        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (arr[mid] == target) {
                return arr[mid];
            } else if (arr[mid] < target) {
                left = mid + 1;
                closest = arr[mid];
            } else {
                right = mid - 1;
                closest = arr[mid];
            }
        }

        if (right >= 0 && Math.abs(arr[right] - target) < Math.abs(closest - target)) {
            closest = arr[right];
        }
        if (left < arr.length && Math.abs(arr[left] - target) < Math.abs(closest - target)) {
            closest = arr[left];
        }

        return closest;
    }
}

