public class Solution {

    private static final int MOD = 1000000007;

    public int maxNiceDivisors(int primeFactors) {
        if (primeFactors == 1) {
            return 1;
        }
        if (primeFactors == 2) {
            return 2;
        }
        if (primeFactors == 3) {
            return 4;
        }
        if (primeFactors == 4) {
            return 6;
        }
        if (primeFactors == 5) {
            return 9;
        }
        if (primeFactors == 6) {
            return 12;
        }

        long result = 1;
        if (primeFactors % 3 == 0) {
            long base = 3;
            long exponent = primeFactors / 3;
            for (int i = 0; i < exponent; i++) {
                result = (result * base) % MOD;
            }
        } else if (primeFactors % 3 == 1) {
            long base = 3;
            long exponent = (primeFactors - 4) / 3;
            for (int i = 0; i < exponent; i++) {
                result = (result * base) % MOD;
            }
            result = (result * 4) % MOD;
        } else {
            long base = 3;
            long exponent = (primeFactors - 2) / 3;
            for (int i = 0; i < exponent; i++) {
                result = (result * base) % MOD;
            }
            result = (result * 2) % MOD;
        }

        return (int) result;
    }
}

