import java.util.LinkedList;
import java.util.Queue;

public class Solution {
    public int shortestPathAllKeys(String[] stringGrid) {
        int m = stringGrid.length;
        int n = stringGrid[0].length();
        int allKeys = 0;
        int startRow = -1;
        int startCol = -1;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                char c = stringGrid[i].charAt(j);
                if (Character.isLowerCase(c)) {
                    allKeys |= (1 << (c - 'a'));
                } else if (c == '@') {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
        boolean[][][] visited = new boolean[m][n][1 << 6];
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{startRow, startCol, 0, 0}); // row, col, keys, steps
        visited[startRow][startCol][0] = true;

        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            int row = curr[0];
            int col = curr[1];
            int keys = curr[2];
            int steps = curr[3];

            if (keys == allKeys) {
                return steps;
            }

            for (int[] dir : directions) {
                int newRow = row + dir[0];
                int newCol = col + dir[1];

                if (newRow >= 0 && newRow < m && newCol >= 0 && newCol < n && stringGrid[newRow].charAt(newCol) != '#') {
                    char c = stringGrid[newRow].charAt(newCol);

                    if (Character.isLowerCase(c)) {
                        int newKeys = keys | (1 << (c - 'a'));
                        if (!visited[newRow][newCol][newKeys]) {
                            visited[newRow][newCol][newKeys] = true;
                            queue.offer(new int[]{newRow, newCol, newKeys, steps + 1});
                        }
                    } else if (Character.isUpperCase(c)) {
                        int keyIndex = c - 'A';
                        if ((keys & (1 << keyIndex)) != 0) {
                            if (!visited[newRow][newCol][keys]) {
                                visited[newRow][newCol][keys] = true;
                                queue.offer(new int[]{newRow, newCol, keys, steps + 1});
                            }
                        }
                    } else {
                        if (!visited[newRow][newCol][keys]) {
                            visited[newRow][newCol][keys] = true;
                            queue.offer(new int[]{newRow, newCol, keys, steps + 1});
                        }
                    }
                }
            }
        }

        return -1;
    }
}

