import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<Integer> splitIntoFibonacci(String num) {
        List<Integer> result = new ArrayList<>();
        backtrack(num, 0, result);
        return result;
    }

    private boolean backtrack(String num, int index, List<Integer> result) {
        if (index == num.length() && result.size() >= 3) {
            return true;
        }

        for (int i = index; i < num.length(); i++) {
            if (i > index && num.charAt(index) == '0') {
                break;
            }

            long currentNum = 0;
            for (int j = index; j <= i; j++) {
                currentNum = currentNum * 10 + (num.charAt(j) - '0');
                if (currentNum > Integer.MAX_VALUE) {
                    break;
                }
            }

            if (currentNum > Integer.MAX_VALUE) {
                continue;
            }

            if (result.size() >= 2) {
                long sum = (long) result.get(result.size() - 1) + (long) result.get(result.size() - 2);
                if (sum != currentNum) {
                    continue;
                }
            }

            result.add((int) currentNum);
            if (backtrack(num, i + 1, result)) {
                return true;
            }
            result.remove(result.size() - 1);
        }

        return false;
    }
}

