public class Solution {
    public int racecar(int target) {
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{0, 1, 0}); // position, speed, steps
        HashSet<String> visited = new HashSet<>();
        visited.add("0,1");

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int position = current[0];
            int speed = current[1];
            int steps = current[2];

            if (position == target) {
                return steps;
            }

            // Option 1: Accelerate
            int newPositionA = position + speed;
            int newSpeedA = speed == 1 ? 2 : speed * 2;
            String stateA = newPositionA + "," + newSpeedA;
            if (Math.abs(newPositionA - target) < 2 * target && !visited.contains(stateA)) {
                queue.offer(new int[]{newPositionA, newSpeedA, steps + 1});
                visited.add(stateA);
            }

            // Option 2: Reverse
            int newSpeedR = speed > 0 ? -1 : 1;
            String stateR = position + "," + newSpeedR;
            if (Math.abs(position - target) < 2 * target && !visited.contains(stateR)) {
                queue.offer(new int[]{position, newSpeedR, steps + 1});
                visited.add(stateR);
            }
        }

        return -1; // Should not happen
    }
}

