import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Queue;
import java.util.Set;
public class Solution {
    public int numBusesToDestination(int[][] routes, int source, int target) {
        if (source == target) {
            return 0;
        }

        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < routes.length; i++) {
            adj.add(new ArrayList<>());
        }

        for (int i = 0; i < routes.length; i++) {
            for (int j = i + 1; j < routes.length; j++) {
                if (intersect(routes[i], routes[j])) {
                    adj.get(i).add(j);
                    adj.get(j).add(i);
                }
            }
        }

        List<Integer> busStops = new ArrayList<>();
        for (int[] route : routes) {
            for (int stop : route) {
                busStops.add(stop);
            }
        }
        busStops = new ArrayList<>(new HashSet<>(busStops));

        if (!busStops.contains(source) || !busStops.contains(target)) {
            return -1;
        }

        List<Integer> sourceBuses = new ArrayList<>();
        for (int i = 0; i < routes.length; i++) {
            for (int stop : routes[i]) {
                if (stop == source) {
                    sourceBuses.add(i);
                    break;
                }
            }
        }

        Queue<Integer> queue = new ArrayDeque<>(sourceBuses);
        Set<Integer> visited = new HashSet<>(sourceBuses);
        int buses = 1;

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                int bus = queue.poll();
                for (int nextBus : adj.get(bus)) {
                    if (!visited.contains(nextBus)) {
                        visited.add(nextBus);
                        boolean targetFound = false;
                        for (int stop : routes[nextBus]) {
                            if (stop == target) {
                                targetFound = true;
                                break;
                            }
                        }
                        if (targetFound) {
                            return buses;
                        }
                        queue.offer(nextBus);
                    }
                }
            }
            buses++;
        }

        return -1;
    }

    private boolean intersect(int[] route1, int[] route2) {
        Set<Integer> set1 = new HashSet<>();
        for (int stop : route1) {
            set1.add(stop);
        }
        for (int stop : route2) {
            if (set1.contains(stop)) {
                return true;
            }
        }
        return false;
    }
}

