import java.util.Arrays;
public class Solution {
    // 1-6 (number of elements in between 1 and 6) = (6-1-1) = 4
    // length of sub seq 2 -> 4C0 3 -> 4C1 ; 4 -> 4c2 ; 5 -> 4C3  6 -> 4C4  4c0 + 4c1 + 4c2 + 4c3 +
    // 4c4 1+4+6+4+1=16
    // 1-5 3c0 + 3c1 + 3c2 + 3c3  = 8
    // 1-4 2c0 + 2c1 2c2 = 4
    // 1-3 1c0 + 1c1  = 2
    // 1-2 1c0 = 1
    public int sumSubseqWidths(int[] nums) {
        Arrays.sort(nums);
        int n = nums.length;
        long sum = 0;
        long mod = 1000000007;
        long powerOf2 = 1;
        for (int i = 0; i < n; i++) {
            sum = (sum + (nums[i] * powerOf2) % mod) % mod;
            powerOf2 = (powerOf2 * 2) % mod;
        }
        powerOf2 = 1;
        for (int i = n - 1; i >= 0; i--) {
            sum = (sum - (nums[i] * powerOf2) % mod + mod) % mod;
            powerOf2 = (powerOf2 * 2) % mod;
        }
        return (int) sum;
    }
}

