        long ans = 0;
        for (int num : arr) {
            long count = 1;
            for (int i = 0; i < arr.length; i++) {
                if (arr[i] * arr[i] > num) break;
                if (num % arr[i] == 0 && arr[i] != num) {
                    int other = num / arr[i];
                    int index = Arrays.binarySearch(arr, other);
                    if (index >= 0) {
                        if (arr[i] == other) {
                            count = (count + dp.getOrDefault(arr[i], 0L) * dp.getOrDefault(arr[i], 0L) % mod) % mod;
                        } else {
                            count = (count + 2 * dp.getOrDefault(arr[i], 0L) * dp.getOrDefault(other, 0L) % mod) % mod;
                        }
                    }
                }
            }
            dp.put(num, count);
            ans = (ans + count) % mod;
        }
        return (int) ans;
    }
}

