import java.util.Arrays;

public class Solution {
    public int numFriendRequests(int[] ages) {
        int n = ages.length;
        int count = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i != j) {
                    if (ages[j] > 0 && ages[i] + 7 * ages[j] > ages[i] && (ages[j] <= 100 || ages[i] >= 100)) {
                        count++;
                    }
                }
            }
        }
        return count;
    }
}

